example.code:
#include <iostream>

int main() {
    // Demonstrate postfix increment
    int c{5};
    std::cout << c << "\n";    // prints 5
    std::cout << c++ << "\n";  // prints 5, then postincrements
    std::cout << c << "\n";    // prints 6

    std::cout << "\n";         // skip a line

    // Demonstrate prefix increment
    c = 5;
    std::cout << c << "\n";    // prints 5
    std::cout << ++c << "\n";  // preincrements to 6, then prints 6
    std::cout << c << "\n";    // prints 6

    return 0;
}

